SELECT dp.sub_category, AVG(dp.unit_cost) AS average_unit_cost
FROM dim_product AS dp
GROUP BY dp.sub_category;

SELECT dp.sub_category, AVG(dp.unit_cost) AS average_unit_cost
FROM dim_product AS dp
GROUP BY dp.sub_category;

SELECT dp.sub_category, AVG(dp.unit_cost) AS average_unit_cost
FROM dim_product AS dp
GROUP BY dp.sub_category;
